data.variablesTransform:
{
  "msg": {
    "create":{
      "integrationId": $state.context.REQUEST.DATA.integration.id,
      "modelId": $state.context.REQUEST.DATA.model.id,
      "message": $state.context.REQUEST.DATA.model.name
        & " synchronization failed. An unexpected error occured. See logs for details",
      "typeId": "Failure",
      "data": $state
    }
  }
}

{
  "payload": [
    data.{      
      "create": {
        "code": name,
        "name": name,
        "externalId": $string(id),
        "typeId": "Production",
        "address": (postalCode) ? {
          "lines": (address1 or address2 or address3) ? [
              address1,
              address2,
              address3
            ],
          "city": city,
          "state": state,
          "postalCode": zip
        },
        "integrationData": $
      },
      "update": {
        "code": name,
        "name": name,

        "address": (postalCode) ? {
          "lines": (address1 or address2 or address3) ? [
            address1,
            address2,
            address3
          ],
          "city": city,
          "state": state,
          "postalCode": zip
        },
        "integrationData":$
      },
      "where": {
        "id": id
      }
    }
  ]
}

